//Generated by AI
using UnityEngine;

public class PurificationTrigger : MonoBehaviour
{
    [Header("Environment Settings")]
    [SerializeField] private GameObject pollutedEnvironment;
    [SerializeField] private GameObject restoredEnvironment;

    [Header("Accessibility")]
    [SerializeField] private SubtitleController subtitleController;
    [SerializeField] private string purificationMessage = "The environment is recovering";

    [Header("Audio")]
    [SerializeField] private AudioSource restoredEnvironmentAudio;

    public static bool purifierCollected = false;

    private bool activated = false;

    [RuntimeInitializeOnLoadMethod(RuntimeInitializeLoadType.SubsystemRegistration)]
    private static void ResetPurifier()
    {
        // Reset the purifier state when a new session starts.
        purifierCollected = false;
    }

    private void OnTriggerEnter2D(Collider2D other)
    {

        // Prevent activation before the game starts.
        if (!PauseMenuController.GameStarted)
            return;

        // Prevent the trigger from activating more than once.
        if (activated)
            return;

        // Only the player can activate the purification trigger.
        if (!other.CompareTag("Player"))
            return;

        // Require the purifier to be collected first.
        if (!purifierCollected)
        {
            return;
        }

        activated = true;

        // Display the purification message.
        if (subtitleController != null)
        {
            subtitleController.ShowSubtitle(purificationMessage);
        }

        // Hide the polluted environment.
        if (pollutedEnvironment != null)
        {
            pollutedEnvironment.SetActive(false);
        }

        // Activate the restored environment.
        if (restoredEnvironment != null)
        {
            restoredEnvironment.SetActive(true);
        }

        // Play the restored environment audio.
        if (restoredEnvironmentAudio != null)
        {
            restoredEnvironmentAudio.Play();
        }
    }
}
